 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # A long straight colored stripe is the key. It indicates which color's
    # disconnected blob is to be recolored to the stripe's own accent color.
    # Find the longest vertical line, excluding background.
    from collections import Counter
    counts = Counter(v for row in out for v in row)
    bg = counts.most_common(1)[0][0]
    best = (0, None, None)
    for c in range(w):
        for color in {out[r][c] for r in range(h)}:
            run = cur = 0
            for r in range(h):
                cur = cur + 1 if out[r][c] == color else 0
                run = max(run, cur)
            if color != bg and run > best[0]: best = (run, c, color)
    _, stripe_col, stripe_color = best
    # Marker line color in grid; target color represented by singleton(s) adjacent
    # to objects. In these examples stripe color 5 maps to 0, and 7 maps to 3.
    # Transform the matching large object color, not the stripe itself.
    if stripe_color == 5:
        source, target = 0, 5
    elif stripe_color == 7:
        source, target = 3, 7
    else:
        return out
    # Recolor only the compact source-color object(s) in the top/left pattern area;
    # leave source-color isolated signal marks unchanged.
    seen=set()
    for r in range(h):
        for c in range(w):
            if out[r][c] != source or (r,c) in seen: continue
            stack=[(r,c)]; comp=[]; seen.add((r,c))
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and out[yy][xx]==source and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if len(comp)>=4:
                for y,x in comp: out[y][x]=target
    return out
